import openpyxl, re
from openpyxl.utils import coordinate_to_tuple, column_index_from_string, get_column_letter

wb=openpyxl.load_workbook('seed_collection_0014_incorrect_sign_3340_input.xlsx', data_only=False)
ws=wb['ETS']
# Build cells: value if not formula else None, formula string
cells={}
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        cell=ws.cell(r,c)
        coord=cell.coordinate
        cells[coord]=(cell.value, r, c)

def col_letter(c):
    return get_column_letter(c)

# Pre-evaluate constants
def is_number(v):
    return isinstance(v,(int,float))

def parse_cell_ref(ref):
    # ref like C8
    m=re.match(r'$([A-Z]+)([0-9]+)$', ref)
    col=column_index_from_string(m.group(1))
    row=int(m.group(2))
    return (row,col)

# Recursive eval with cache and visiting
visiting=set()
def eval_coord(coord):
    val, r, c = cells[coord]
    if is_number(val):
        return float(val)
    if val is None:
        return 0.0
    if isinstance(val,str) and val.startswith('='):
        if coord in visiting:
            raise Exception('circular '+coord)
        visiting.add(coord)
        expr=val[1:]
        res=eval_expr(expr, r, c)
        visiting.discard(coord)
        cells[coord]=(res,r,c)
        return res
    if is_number(val):
        return float(val)
    return 0.0

def eval_expr(expr, row, col):
    expr=expr.strip()
    # handle leading +/-
    # replace cell refs and ranges in SUM
    # We'll parse SUM functions first
    def repl_sum(m):
        rng=m.group(1)
        return str(sum_range(rng))
    # Need not replace inside? SUM only.
    expr=re.sub(r'SUM\(([^)]+)\)', repl_sum, expr, flags=re.IGNORECASE)
    # Now replace cell refs with values, but not numbers? replace all A1 refs
    expr=re.sub(r'(?<![A-Z0-9])([A-Z]{1,2}[0-9]+)(?![A-Z0-9])', repl_ref, expr)
    # Excel formulas use *, /, +, -; Python mostly okay except unary? eval handles.
    # Remove leading '=' already.
    # Remove + unary? Python eval supports.
    return eval(expr, {"__builtins__":None}, {})

def sum_range(rng):
    # rng like C8:I8
    m=re.match(r'([A-Z]+)([0-9]+):([A-Z]+)([0-9]+)', rng)
    c1=column_index_from_string(m.group(1)); r1=int(m.group(2))
    c2=column_index_from_string(m.group(3)); r2=int(m.group(4))
    total=0.0
    for rr in range(min(r1,r2), max(r1,r2)+1):
        for cc in range(min(c1,c2), max(c1,c2)+1):
            total+=eval_coord(f'{get_column_letter(cc)}{rr}')
    return total

def repl_ref(m):
    ref=m.group(1)
    return str(eval_coord(ref))

# Evaluate all
for coord in list(cells.keys()):
    val,r,c=cells[coord]
    if isinstance(val,str) and val.startswith('='):
        try:
            v=eval_coord(coord)
            cells[coord]=(v,r,c)
        except Exception as e:
            print('ERR',coord,val,e)

# Print selected values
for r in range(1, ws.max_row+1):
    if any(cells.get(f'{get_column_letter(c)}{r}',(None,))[0] is not None for c in range(1,13)):
        vals=[]
        for c in range(1,13):
            coord=f'{get_column_letter(c)}{r}'
            v=cells[coord][0]
            vals.append(v)
        print(r, vals)
